define('taoQtiItem/qtiCreator/editor/styleEditor/colorSelector',['jquery', 'lodash', 'i18n', 'taoQtiItem/qtiCreator/editor/styleEditor/styleEditor', 'taoQtiItem/qtiCreator/helper/popup', 'lib/farbtastic/farbtastic'], function ($, _, __, styleEditor) {
  'use strict';
  function rgbToHex(color) {
    function toHexPair(inp) {
      return "0".concat(parseInt(inp, 10).toString(16)).slice(-2);
    }
    if (!_.isString(color)) {
      return color;
    }
    var rgbArr = /rgb\s*\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*\)/i.exec(color);
    if (!_.isArray(rgbArr) || rgbArr.length !== 4) {
      return color;
    }
    return "#".concat(toHexPair(rgbArr[1])).concat(toHexPair(rgbArr[2])).concat(toHexPair(rgbArr[3]));
  }
  var colorSelector = function colorSelector() {
    var colorPicker = $('.item-editor-color-picker'),
      widget = colorPicker.find('.color-picker'),
      widgetBox = colorPicker.find('.color-picker-container'),
      titleElement = colorPicker.find('#color-picker-title'),
      input = colorPicker.find('#color-picker-input'),
      resetButtons = colorPicker.find('.reset-button'),
      colorTriggers = colorPicker.find('.color-trigger'),
      colorTriggerLabels = colorPicker.find('label'),
      cssVariablesRootSelector = styleEditor.getConfig().cssVariablesRootSelector,
      $doc = $(document);
    var widgetObj;
    var colorBindings = {
      'background-color': {
        varName: '--styleeditor-bg-color',
        propSelector: 'body div.qti-item, body div.qti-item .qti-associateInteraction .result-area > li > .target',
        propName: 'background-color'
      },
      'text-color': {
        varName: '--styleeditor-text-color',
        propSelector: 'body div.qti-item',
        propName: 'color'
      },
      'border-color': {
        varName: '--styleeditor-border-color',
        propSelector: 'body div.qti-item .solid,body div.qti-item .matrix, body div.qti-item table.matrix th, body div.qti-item table.matrix td',
        propName: 'border-color'
      },
      'table-heading-color': {
        varName: '--styleeditor-table-heading-bg-color',
        propSelector: 'body div.qti-item .matrix th',
        propName: 'background-color'
      }
    };
    var setTitle = function setTitle(trigger) {
      titleElement.text(trigger.parent().find('label').text());
    };
    var setTriggerColor = function setTriggerColor() {
      colorTriggers.each(function () {
        var $trigger = $(this),
          target = $trigger.data('target'),
          style = styleEditor.getStyle() || {};
        var shouldFireStyleChange = false;
        var {
          varName,
          propSelector,
          propName
        } = colorBindings[target];
        var val = style[cssVariablesRootSelector] && style[cssVariablesRootSelector][varName];
        if (!val) {
          val = style[propSelector] && style[propSelector][propName];
          shouldFireStyleChange = true;
        }
        if (val) {
          $trigger.css('background-color', val);
          $trigger.attr('title', rgbToHex(val));
          if (shouldFireStyleChange) {
            styleEditorApply(target, val);
          }
        } else {
          $trigger.css('background-color', '');
          $trigger.attr('title', __('No value set'));
        }
      });
    };
    var styleEditorApply = function styleEditorApply(target, val) {
      var {
        varName,
        propSelector,
        propName
      } = colorBindings[target];
      styleEditor.apply(cssVariablesRootSelector, varName, val);
      styleEditor.apply(propSelector, propName, val ? "var(".concat(varName, ")") : null);
    };
    widgetObj = $.farbtastic(widget).linkTo(input);
    widget.on('colorchange.farbtastic', function (e, color) {
      styleEditorApply(widget.prop('target'), color);
      setTriggerColor();
    });
    setTriggerColor();
    colorTriggers.add(colorTriggerLabels).on('click', function () {
      var $tmpTrigger = $(this),
        $trigger = this.nodeName.toLowerCase() === 'label' ? $tmpTrigger.parent().find('.color-trigger') : $tmpTrigger;
      widget.prop('target', $trigger.data('target'));
      widgetBox.hide();
      setTitle($trigger);
      widgetObj.setColor(rgbToHex($trigger.css('background-color')));
      widgetBox.show();
    });
    $doc.on('mouseup', function (e) {
      if ($(e.target).hasClass('closer')) {
        widgetBox.hide();
        return false;
      }
      if (!widgetBox.is(e.target) && widgetBox.has(e.target).length === 0) {
        widgetBox.hide();
        return false;
      }
    });
    $doc.on('keyup', function (e) {
      if (e.keyCode === 27) {
        widgetBox.hide();
        return false;
      }
    });
    resetButtons.on('click', function () {
      var $this = $(this),
        $colorTrigger = $this.parent().find('.color-trigger'),
        target = $colorTrigger.data('target');
      styleEditorApply(target, null);
      setTriggerColor();
    });
    $doc.on('customcssloaded.styleeditor', setTriggerColor);
  };
  return colorSelector;
});
