define('taoQtiItem/qtiCreator/widgets/helpers/qtiIdentifier',['module', 'i18n'], function (module, __) {
  'use strict';

  var qtiIdPattern = module.config().qtiIdPattern || '/^[a-zA-Z_]{1}[a-zA-Z0-9_.-]*$/u';
  var [, patternContent, flags] = qtiIdPattern.match(/^\/(.+)\/(\w*)$/);
  var defaultInvalidQtiIdMessage = __('Identifiers must start with a letter or an underscore and contain only letters, numbers, dots, underscores ( _ ), or hyphens ( - ).');
  var invalidQtiIdMessage = module.config().invalidQtiIdMessage || defaultInvalidQtiIdMessage;
  var isDisabled = module.config().isDisabled || false;
  return {
    pattern: new RegExp(patternContent, flags),
    invalidQtiIdMessage,
    maxQtiIdLength: 32,
    isDisabled
  };
});
